use super::*;

#[test]
fn test_whnf_cache_cleared_on_local_context_mut() {
    // Tests that calling local_context_mut() clears the WHNF cache.
    // This is critical for correctness: WHNF results may depend on free
    // variables that change meaning when the local context is modified.
    let env = Environment::new();
    let mut tc = TypeChecker::new(&env);

    // Perform a WHNF reduction to populate the cache
    // (λ x : Prop. x) Prop -> Prop (beta reduces to Prop)
    let lam = Expr::lam(BinderInfo::Default, Expr::prop(), Expr::bvar(0));
    let app = Expr::app(lam.clone(), Expr::prop());
    let whnf_result = tc.whnf(&app);
    assert_eq!(
        whnf_result,
        Expr::prop(),
        "whnf of (λ x : Prop. x) Prop should be Prop"
    );

    // Verify cache has an entry
    assert!(
        !tc.whnf_cache.borrow().is_empty(),
        "Cache should have entry after WHNF"
    );

    // Call local_context_mut() which should clear the cache
    let ctx_mut = tc.local_context_mut();
    let _id = ctx_mut.push(Name::anon(), Expr::prop(), BinderInfo::Default);

    // Verify cache was actually cleared
    assert!(
        tc.whnf_cache.borrow().is_empty(),
        "Cache should be empty after local_context_mut()"
    );

    // The WHNF should still produce the same result (correctness check).
    let result = tc.whnf(&app);
    assert_eq!(result, Expr::prop());
}

// D4 transparency tests are in env/tests.rs (needs private field access)

/// Helper: build a simple let expression for idempotence tests.
fn test_let(ty: Expr, val: Expr, body: Expr) -> Expr {
    Expr::let_named(Name::anon(), ty, val, body, false)
}

/// Test WHNF idempotence property explicitly (not just debug assertion).
///
/// Contract: `whnf(whnf(e)) == whnf(e)` for all expressions.
/// This test verifies the idempotence claim in mod.rs:1762, 1767.
/// The debug assertion (line 1784-1790) only runs in debug builds.
#[test]
fn test_whnf_idempotent() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    let test_cases: Vec<Expr> = vec![
        Expr::prop(),
        Expr::type_(),
        Expr::bvar(0),
        test_let(Expr::type_(), Expr::prop(), Expr::bvar(0)),
        test_let(
            Expr::type_(),
            test_let(Expr::type_(), Expr::prop(), Expr::bvar(0)),
            Expr::bvar(0),
        ),
        Expr::app(
            Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
            Expr::prop(),
        ),
        Expr::app(
            Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
            Expr::app(
                Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
                Expr::type_(),
            ),
        ),
        Expr::from_kind(ExprKind::Sort(Level::succ(Level::succ(Level::zero())))),
        Expr::pi(
            BinderInfo::Default,
            Expr::prop(),
            test_let(Expr::type_(), Expr::type_(), Expr::bvar(0)),
        ),
        Expr::lam(
            BinderInfo::Default,
            Expr::prop(),
            test_let(Expr::type_(), Expr::type_(), Expr::bvar(0)),
        ),
    ];

    for e in test_cases {
        let whnf1 = tc.whnf(&e);
        let whnf2 = tc.whnf(&whnf1);
        assert_eq!(
            whnf1, whnf2,
            "WHNF not idempotent for {e:?}\nFirst WHNF: {whnf1:?}\nSecond WHNF: {whnf2:?}"
        );
    }
}

