/// Test whnf_with_transparency respects TransparencyMode for delta reduction.
///
/// Sets up constants with different reducibility levels and verifies
/// that each TransparencyMode only unfolds what it should.
#[test]
fn test_whnf_with_transparency_reducible_mode() {
    use crate::env::{Reducibility, TransparencyMode};

    let mut env = Environment::new();

    // Add a reducible definition: `myTrue := Prop`
    let mut info_reducible = crate::env::ConstantInfo::new(
        Name::from_string("myReducible"),
        vec![],
        Expr::type_(),
        Some(Expr::prop()),
        false,
    );
    info_reducible.reducibility = Reducibility::Reducible;
    env.extend_constants_unchecked(std::iter::once(info_reducible));

    // Add a semireducible definition: `mySemi := Prop`
    let mut info_semi = crate::env::ConstantInfo::new(
        Name::from_string("mySemi"),
        vec![],
        Expr::type_(),
        Some(Expr::prop()),
        false,
    );
    info_semi.reducibility = Reducibility::Regular(0);
    env.extend_constants_unchecked(std::iter::once(info_semi));

    // Add an irreducible definition: `myIrred := Prop`
    let mut info_irred = crate::env::ConstantInfo::new(
        Name::from_string("myIrred"),
        vec![],
        Expr::type_(),
        Some(Expr::prop()),
        false,
    );
    info_irred.reducibility = Reducibility::Irreducible;
    env.extend_constants_unchecked(std::iter::once(info_irred));

    let tc = TypeChecker::new(&env);

    let reducible_expr = Expr::const_(Name::from_string("myReducible"), vec![]);
    let semi_expr = Expr::const_(Name::from_string("mySemi"), vec![]);
    let irred_expr = Expr::const_(Name::from_string("myIrred"), vec![]);

    // Reducible mode: only unfolds @[reducible]
    let r = tc.whnf_with_transparency(&reducible_expr, TransparencyMode::Reducible);
    assert_eq!(
        r,
        Expr::prop(),
        "Reducible const should unfold in Reducible mode"
    );

    let r = tc.whnf_with_transparency(&semi_expr, TransparencyMode::Reducible);
    assert_eq!(
        r, semi_expr,
        "Semireducible const should NOT unfold in Reducible mode"
    );

    let r = tc.whnf_with_transparency(&irred_expr, TransparencyMode::Reducible);
    assert_eq!(
        r, irred_expr,
        "Irreducible const should NOT unfold in Reducible mode"
    );
}

