fn build_single_projection_transparency_env() -> (Environment, Name, Name) {
    use crate::env::{Declaration, Reducibility};
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};
    use crate::level::Level;

    let mut env = Environment::new();

    let semi_name = Name::from_string("semiProp");
    env.add_decl(Declaration::Definition {
        name: semi_name.clone(),
        level_params: vec![],
        type_: Expr::type_(),
        value: Expr::prop(),
        is_reducible: true,
    })
    .expect("semiProp declaration should be valid");
    assert!(
        env.set_reducibility(&semi_name, Reducibility::Regular(0)),
        "set_reducibility should succeed for semiProp"
    );

    // inductive Single : Type 1 where | mk : Type -> Single
    let single_name = Name::from_string("Single");
    let single_ref = Expr::const_(single_name.clone(), vec![]);
    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: single_name.clone(),
            type_: Expr::sort(Level::succ(Level::succ(Level::zero()))),
            constructors: vec![Constructor {
                name: Name::from_string("Single.mk"),
                type_: Expr::pi(BinderInfo::Default, Expr::type_(), single_ref.clone()),
            }],
        }],
    })
    .expect("Single inductive declaration should be valid");

    (env, single_name, semi_name)
}

fn single_mk_expr(value: Expr) -> Expr {
    Expr::app(Expr::const_(Name::from_string("Single.mk"), vec![]), value)
}

/// Regression test for WHNF core unification:
/// projection reduction under `whnf_with_transparency` must re-enter WHNF with
/// the same transparency mode when the projection succeeds.
#[test]
fn test_whnf_with_transparency_proj_result_respects_mode() {
    use crate::env::TransparencyMode;

    let (env, single_name, semi_name) = build_single_projection_transparency_env();

    let tc = TypeChecker::new(&env);

    let semi_const = Expr::const_(semi_name, vec![]);
    let single_val = single_mk_expr(semi_const.clone());
    let proj = Expr::proj(single_name, 0, single_val);

    let reducible = tc.whnf_with_transparency(&proj, TransparencyMode::Reducible);
    assert_eq!(
        reducible, semi_const,
        "Reducible mode should not unfold semireducible projection result"
    );

    let default = tc.whnf_with_transparency(&proj, TransparencyMode::Default);
    assert_eq!(
        default,
        Expr::prop(),
        "Default mode should unfold semireducible projection result"
    );
}

/// Regression test for WHNF core unification:
/// projection reduction must recurse when the extracted field is itself a
/// projection expression.
///
/// Lean 4's `whnfCore` calls `go e` after successful projection extraction,
/// even when `e` is another `.proj`. The shared reducer must preserve that
/// behavior under the caller's transparency mode.
#[test]
fn test_whnf_with_transparency_proj_result_recurses_when_field_is_proj() {
    use crate::env::TransparencyMode;

    let (env, single_name, semi_name) = build_single_projection_transparency_env();

    let tc = TypeChecker::new(&env);

    let semi_const = Expr::const_(semi_name, vec![]);
    let inner_proj = Expr::proj(single_name.clone(), 0, single_mk_expr(semi_const.clone()));
    let outer_proj = Expr::proj(single_name, 0, single_mk_expr(inner_proj));

    let reducible = tc.whnf_with_transparency(&outer_proj, TransparencyMode::Reducible);
    assert_eq!(
        reducible, semi_const,
        "Reducible mode should recurse through nested projection results without unfolding semireducible defs"
    );

    let default = tc.whnf_with_transparency(&outer_proj, TransparencyMode::Default);
    assert_eq!(
        default,
        Expr::prop(),
        "Default mode should recurse through nested projection results and unfold semireducible defs"
    );
}

// ============================================================================
// Transparency-aware reduction vs. kernel completeness (#3208 follow-up)
//
// These tests pin the contract that `whnf_with_transparency` honors the Lean 4
// `@[irreducible]`/`@[reducible]` hints bridged from `.olean` (an elaboration-
// time transparency concern), while the kernel type-checker's `whnf`/`is_def_eq`
// stays COMPLETE by unfolding everything except `Opaque`. Skipping irreducible
// unfolding in the kernel path would incompletely reject valid def-eq; these
// tests guard against that regression.
// ============================================================================

/// Build an environment with one `@[irreducible]` def and one `@[reducible]`
/// def, both whose value is `Prop`. Returns the env plus the const exprs.
fn build_irreducible_reducible_env() -> (Environment, Expr, Expr) {
    use crate::env::Reducibility;

    let mut env = Environment::new();

    let mut irred = crate::env::ConstantInfo::new(
        Name::from_string("transpIrred"),
        vec![],
        Expr::type_(),
        Some(Expr::prop()),
        false,
    );
    irred.reducibility = Reducibility::Irreducible;
    env.extend_constants_unchecked(std::iter::once(irred));

    let mut red = crate::env::ConstantInfo::new(
        Name::from_string("transpRed"),
        vec![],
        Expr::type_(),
        Some(Expr::prop()),
        false,
    );
    red.reducibility = Reducibility::Reducible;
    env.extend_constants_unchecked(std::iter::once(red));

    let irred_expr = Expr::const_(Name::from_string("transpIrred"), vec![]);
    let red_expr = Expr::const_(Name::from_string("transpRed"), vec![]);
    (env, irred_expr, red_expr)
}

/// A `Default`-transparency WHNF must NOT unfold an `@[irreducible]` def — the
/// constant stays in head position (matches the elaborator's def-eq behavior).
#[test]
fn test_whnf_default_transparency_skips_irreducible() {
    let (env, irred_expr, _red_expr) = build_irreducible_reducible_env();
    let tc = TypeChecker::new(&env);

    let r = tc.whnf_with_transparency(&irred_expr, TransparencyMode::Default);
    assert_eq!(
        r, irred_expr,
        "Default transparency must leave @[irreducible] def folded (no delta unfold)"
    );
}

/// A `Default`-transparency WHNF DOES eagerly unfold an `@[reducible]` def.
#[test]
fn test_whnf_default_transparency_unfolds_reducible() {
    let (env, _irred_expr, red_expr) = build_irreducible_reducible_env();
    let tc = TypeChecker::new(&env);

    let r = tc.whnf_with_transparency(&red_expr, TransparencyMode::Default);
    assert_eq!(
        r,
        Expr::prop(),
        "Default transparency must eagerly unfold @[reducible] def to its value"
    );
}

/// An `All`-transparency WHNF unfolds even `@[irreducible]` defs, AND the kernel
/// type-checker (`whnf` / `is_def_eq`) still unfolds the same irreducible def —
/// confirming kernel completeness is preserved (the kernel has no transparency).
#[test]
fn test_whnf_all_transparency_unfolds_irreducible() {
    let (env, irred_expr, _red_expr) = build_irreducible_reducible_env();
    let tc = TypeChecker::new(&env);

    // All-mode transparency: unfolds irreducible.
    let r_all = tc.whnf_with_transparency(&irred_expr, TransparencyMode::All);
    assert_eq!(
        r_all,
        Expr::prop(),
        "All transparency must unfold @[irreducible] def to its value"
    );

    // Kernel type-checker path: `whnf` (full delta, no transparency) must ALSO
    // unfold the irreducible def — otherwise the kernel would be INCOMPLETE.
    let r_kernel = tc.whnf(&irred_expr);
    assert_eq!(
        r_kernel,
        Expr::prop(),
        "Kernel whnf must unfold @[irreducible] def (completeness preserved)"
    );

    // And kernel def-eq must therefore see the irreducible const as def-eq to
    // its unfolded value — the property a transparency-skipping kernel would break.
    let tc2 = TypeChecker::new(&env);
    assert!(
        tc2.is_def_eq(&irred_expr, &Expr::prop()),
        "Kernel is_def_eq must equate @[irreducible] def with its value (completeness)"
    );
}

